#include <atomic>

struct Node { int value; std::atomic<Node*> next; };
std::atomic<Node*> head;

Node* pop() {                              // assumes the stack is not empty
  Node* old = head.load(std::memory_order_acquire);
  Node* next = old->next.load();           // T1 is preempted here
  head.compare_exchange_strong(old, next);
  return old;
}

